SELECT JSON_OBJECT('kind','runtime','database',DATABASE(),'serverUuid',@@server_uuid,'mysqlVersion',VERSION(),'pageSize',@@innodb_page_size,'rowFormat',@@innodb_default_row_format,'sqlMode',@@session.sql_mode);
SELECT JSON_OBJECT('kind','ledger','migrationId',migration_id,'sha256',sha256,'status',status,'environment',target_environment,'deleted',deleted+0) FROM infra_release_migration WHERE migration_id='20261003_dcc_legacy_source_name_occupancy';
SELECT JSON_OBJECT('kind','table','table',TABLE_NAME,'engine',ENGINE,'charset',SUBSTRING_INDEX(TABLE_COLLATION,'_',1),'collation',TABLE_COLLATION,'rowFormat',ROW_FORMAT) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('dcc_legacy_source_name_scope','dcc_legacy_source_name_evidence','dcc_source_name_reservation') ORDER BY TABLE_NAME;
SELECT JSON_OBJECT('kind','column','table',TABLE_NAME,'name',COLUMN_NAME,'ordinal',ORDINAL_POSITION,'type',COLUMN_TYPE,'nullable',IS_NULLABLE,'charset',CHARACTER_SET_NAME,'collation',COLLATION_NAME,'default',COLUMN_DEFAULT,'precision',DATETIME_PRECISION,'extra',TRIM(REPLACE(EXTRA,'DEFAULT_GENERATED','')),'expression',GENERATION_EXPRESSION) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('dcc_legacy_source_name_scope','dcc_legacy_source_name_evidence','dcc_source_name_reservation') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT JSON_OBJECT('kind','index','table',TABLE_NAME,'name',INDEX_NAME,'ordinal',SEQ_IN_INDEX,'column',COLUMN_NAME,'prefix',SUB_PART,'unique',IF(NON_UNIQUE=0,CAST('true' AS JSON),CAST('false' AS JSON)),'type',INDEX_TYPE,'direction',COLLATION,'expression',EXPRESSION,'visible',IS_VISIBLE) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('dcc_legacy_source_name_scope','dcc_legacy_source_name_evidence','dcc_source_name_reservation') ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX;
SELECT JSON_OBJECT('kind','check','table',t.TABLE_NAME,'expression',c.CHECK_CLAUSE,'enforced',t.ENFORCED) FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME IN ('dcc_legacy_source_name_scope','dcc_legacy_source_name_evidence','dcc_source_name_reservation') AND t.CONSTRAINT_TYPE='CHECK' ORDER BY t.TABLE_NAME,t.CONSTRAINT_NAME;
